import 'dart:async';\nimport 'package:flutter/material.dart';\nimport 'package:google_maps_flutter/google_maps_flutter.dart';\nimport 'package:geolocator/geolocator.dart';\nimport '../../../core/theme/seek7_theme.dart';\nimport '../../../shared/widgets/seek7_widgets.dart';\n\nclass LiveMiningScreen extends StatefulWidget {\n  const LiveMiningScreen({super.key});\n  @override State<LiveMiningScreen> createState() => _LiveMiningScreenState();\n}\n\nclass _LiveMiningScreenState extends State<LiveMiningScreen> {\n  static const madrid = LatLng(40.4168, -3.7038);\n  GoogleMapController? map;\n  StreamSubscription<Position>? location;\n  Timer? runTimer, rewardTimer;\n  int seconds = 1200, mined = 0, rewardSeconds = 0;\n  bool locationReady = false, watching = false, activated = false;\n  String? consumedSpot;\n  double? lat, lng;\n\n  final markers = <Marker>{\n    const Marker(markerId: MarkerId('gold1'), position: LatLng(40.4176, -3.7031), infoWindow: InfoWindow(title: 'GOLD SPOT', snippet: '€0.20')),\n    const Marker(markerId: MarkerId('gold2'), position: LatLng(40.4157, -3.7050), infoWindow: InfoWindow(title: 'GOLD SPOT', snippet: '€0.35')),\n    const Marker(markerId: MarkerId('gold3'), position: LatLng(40.4182, -3.7009), infoWindow: InfoWindow(title: 'GOLD SPOT', snippet: '€0.15')),\n  };\n\n  @override void initState() { super.initState(); start(); }\n  Future<void> start() async {\n    runTimer = Timer.periodic(const Duration(seconds: 1), (_) {\n      if (!mounted) return;\n      if (seconds <= 1) { runTimer?.cancel(); setState(() => seconds = 0); }\n      else setState(() => seconds--);\n    });\n    if (!await Geolocator.isLocationServiceEnabled()) return;\n    var permission = await Geolocator.checkPermission();\n    if (permission == LocationPermission.denied) permission = await Geolocator.requestPermission();\n    if (permission == LocationPermission.denied || permission == LocationPermission.deniedForever) return;\n    final p = await Geolocator.getCurrentPosition();\n    updatePosition(p);\n    location = Geolocator.getPositionStream(locationSettings: const LocationSettings(accuracy: LocationAccuracy.high, distanceFilter: 5)).listen(updatePosition);\n  }\n\n  void updatePosition(Position p) {\n    if (!mounted) return;\n    setState(() { lat = p.latitude; lng = p.longitude; locationReady = true; });\n    map?.animateCamera(CameraUpdate.newLatLng(LatLng(p.latitude, p.longitude)));\n  }\n\n  void mineSpot(String id) {\n    if (!locationReady || watching || mined >= 5 || seconds == 0 || consumedSpot == id) return;\n    setState(() { consumedSpot = id; watching = true; activated = false; rewardSeconds = 5; });\n    rewardTimer?.cancel();\n    rewardTimer = Timer.periodic(const Duration(seconds: 1), (_) {\n      if (!mounted || !watching) return;\n      if (rewardSeconds <= 1) { rewardTimer?.cancel(); setState(() { rewardSeconds = 0; activated = true; }); }\n      else setState(() => rewardSeconds--);\n    });\n  }\n\n  void leaveVideo() {\n    rewardTimer?.cancel();\n    setState(() { watching = false; activated = false; });\n  }\n\n  void activateMoney() {\n    if (!activated) return;\n    rewardTimer?.cancel();\n    setState(() { mined++; watching = false; activated = false; });\n    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('€0.20 ACTIVATED IN WALLET'), behavior: SnackBarBehavior.floating));\n  }\n\n  @override void dispose() { runTimer?.cancel(); location?.cancel(); rewardTimer?.cancel(); super.dispose(); }\n  String get clock => (seconds ~/ 60).toString().padLeft(2, '0') + ':' + (seconds % 60).toString().padLeft(2, '0');\n\n  @override Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('SEEK RUN'), actions: [Padding(padding: const EdgeInsets.only(right: 18), child: Center(child: Text(clock, style: const TextStyle(color: Seek7Colors.goldBright, fontWeight: FontWeight.w800))))]),\n      body: Stack(children: [\n        GoogleMap(initialCameraPosition: const CameraPosition(target: madrid, zoom: 16), myLocationEnabled: locationReady, myLocationButtonEnabled: true, zoomControlsEnabled: false, markers: markers, onMapCreated: (c) => map = c),\n        Positioned(top: 16, left: 16, right: 16, child: _status()),\n        Positioned(left: 16, right: 16, bottom: 22, child: GoldButton(label: locationReady ? 'WALK & FIND GOLD  •  ' + mined.toString() + '/5' : 'ENABLE LOCATION', onPressed: locationReady ? () => mineSpot('gold1') : () {})),\n        if (watching) _experience(),\n      ]),\n    );\n  }\n\n  Widget _status() => Container(padding: const EdgeInsets.all(16), decoration: BoxDecoration(color: Seek7Colors.surface.withValues(alpha: .94), borderRadius: BorderRadius.circular(20)), child: Row(children: [const Icon(Icons.location_on_rounded, color: Seek7Colors.gold), const SizedBox(width: 10), Expanded(child: Text(locationReady ? 'GPS ACTIVE  •  WALK THE CITY' : 'LOCATION REQUIRED', style: const TextStyle(fontSize: 11, fontWeight: FontWeight.w800, letterSpacing: 1.1))), Text(mined.toString() + '/5', style: const TextStyle(color: Seek7Colors.goldBright, fontWeight: FontWeight.w900))]));\n\n  Widget _experience() => Positioned.fill(child: Container(color: Colors.black.withValues(alpha: .72), child: Center(child: Container(margin: const EdgeInsets.all(24), padding: const EdgeInsets.all(24), decoration: BoxDecoration(color: Seek7Colors.surface, borderRadius: BorderRadius.circular(28)), child: Column(mainAxisSize: MainAxisSize.min, children: [\n    const Text('GOLD SPOT', style: TextStyle(color: Seek7Colors.goldBright, letterSpacing: 2, fontSize: 11)),\n    const SizedBox(height: 10), const Text('Sponsored experience', style: TextStyle(fontSize: 25, fontWeight: FontWeight.w800)),\n    const SizedBox(height: 8), Text(activated ? 'MONEY ACTIVATED' : 'Leave now and this opportunity dies.', textAlign: TextAlign.center, style: const TextStyle(color: Seek7Colors.muted)),\n    const SizedBox(height: 20), Container(height: 170, decoration: BoxDecoration(color: const Color(0xFF20252B), borderRadius: BorderRadius.circular(20)), child: Center(child: activated ? const Icon(Icons.attach_money_rounded, size: 90, color: Seek7Colors.goldBright) : Column(mainAxisAlignment: MainAxisAlignment.center, children: [const Icon(Icons.play_circle_fill_rounded, size: 56, color: Seek7Colors.gold), Text(rewardSeconds.toString(), style: const TextStyle(fontSize: 30, fontWeight: FontWeight.w900, color: Seek7Colors.goldBright))]))),\n    const SizedBox(height: 18),\n    GoldButton(label: activated ? 'ACTIVATE +€0.20' : 'LEAVE • €0', onPressed: activated ? activateMoney : leaveVideo),\n  ]))));\n}